(r/'artifacts/replica/windows-download/matchoption-motion.html').write_text('<!doctype html><meta charset="utf-8"><title>MatchOption motion · original isolation</title><link rel="stylesheet" href="matchoption-original.css"><style>body{padding:30px}.match-option{width:240px;margin:14px 0}.match-option.probe-hover{background:#383b44;border-color:#a7b1ff}</style><button type="button" id="match-motion-record">Measure MatchOption motion</button><div id="fixtures"></div><script>\nconst rows=[];\ndocument.getElementById(\'match-motion-record\').onclick=async()=>{\n rows.length=0;\n for(const scenario of [\'normal-hover\',\'selected-hover\',\'select\',\'unselect\',\'hover-reverse\']){\n  const el=document.createElement(\'label\');el.className=\'match-option\';el.innerHTML=\'<input type="radio"><span><span class="mono">demo.customers</span><small>Same name as the source.</small></span><b class="match-badge"></b>\';el.style.transition=\'none\';const radio=el.querySelector(\'input\');radio.checked=[\'selected-hover\',\'unselect\'].includes(scenario);document.getElementById(\'fixtures\').append(el);getComputedStyle(el).backgroundColor;el.style.transition=\'\';getComputedStyle(el).backgroundColor;\n  if(scenario===\'select\')radio.checked=true;else if(scenario===\'unselect\')radio.checked=false;else el.classList.add(\'probe-hover\');getComputedStyle(el).backgroundColor;\n  let animations=el.getAnimations();for(const a of animations){a.pause();a.currentTime=0;}let duration=null;\n  if(scenario===\'hover-reverse\'){for(const a of animations)a.currentTime=30;getComputedStyle(el).backgroundColor;el.classList.remove(\'probe-hover\');getComputedStyle(el).backgroundColor;animations=el.getAnimations();for(const a of animations){a.pause();a.currentTime=0;}duration=animations.find(a=>a.transitionProperty===\'background-color\')?.effect.getTiming().duration;}\n  for(const ms of [0,.5,8,16,30,40,60,80,120,160]){for(const a of animations)a.currentTime=ms;const s=getComputedStyle(el);rows.push({scenario,ms,bg:s.backgroundColor,border:s.borderColor,shadow:s.boxShadow,reverseDuration:duration});}el.remove();\n }\n const response=await fetch(\'/evidence/source-sidebar.json\',{method:\'POST\',headers:{\'Content-Type\':\'application/json\'},body:JSON.stringify({dpr:devicePixelRatio,reduced:matchMedia(\'(prefers-reduced-motion: reduce)\').matches,rows})});if(!response.ok)throw Error(\'Example evidence failed\');document.getElementById(\'match-motion-record\').textContent=\'MatchOption motion recorded\';\n};</script>')
